sys_script_include.script:
var LeaveBalanceAjax = Class.create();
LeaveBalanceAjax.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

	getBalance: function() {
        var user = this.getParameter('sysparm_user');
        var leaveType = this.getParameter('sysparm_leave_type');
        var balance = 0;

        // Query your Leave Balance table
        var grBalance = new GlideRecord('x_2250616_leave_0_employee_leave_balance'); 
        grBalance.addQuery('employee', user);
        grBalance.query();

        if (grBalance.next()) {
            // Map the dropdown choice to the correct column on the balance table
            if (leaveType == 'sick') {
                balance = grBalance.getValue('sick_balance');
            } else if (leaveType == 'casual') {
                balance = grBalance.getValue('casual_balance');
            } else if (leaveType == 'annual') {
                balance = grBalance.getValue('annual_balance');
            } else if (leaveType == 'emergency') {
                balance = grBalance.getValue('emergency_balance');
            } else if (leaveType == 'maternity') {
                balance = grBalance.getValue('maternity_balance');
            } else if (leaveType == 'paternity') {
                balance = grBalance.getValue('paternity_balance');
            }
        }

        return balance || 0; // Return the balance, or 0 if no record is found
    },

    type: 'LeaveBalanceAjax'
});
